{"action":"run_computation","summary":"Independently enumerate the bounded \(c=6\) partition--Pieri matrices, perform exact unimodular unit-pivot reduction, and extract and sum their quotient ranks.","script":"import json, hashlib

lower=(2,2,0,0,0,0,0,0)
upper=(4,4,4,4,4,4,4,4)
degrees=list(range(4,33))
hdegrees=[1,2,3,4]

def parts(pos=0, prev=4, cur=()):
    if pos==8:
        yield cur; return
    lo=lower[pos]; hi=min(prev,upper[pos])
    for a in range(hi,lo-1,-1):
        yield from parts(pos+1,a,cur+(a,))

P=sorted(parts(), reverse=True)
bydeg={d:[p for p in P if sum(p)==d] for d in degrees}

def horiz(mu,la):
    # mu/la is a horizontal strip (with la padded to length 8).
    return all(mu[i]>=la[i]>= (mu[i+1] if i<7 else 0) for i in range(8))

def unit_reduce(A):
    # Integer row/column additions, swaps, and sign changes only.
    A=[r[:] for r in A]
    m=len(A); n=len(A[0]) if m else 0; k=0
    while True:
        found=None
        for i in range(k,m):
            for j in range(k,n):
                if abs(A[i][j])==1:
                    found=(i,j); break
            if found: break
        if not found: break
        i,j=found
        A[k],A[i]=A[i],A[k]
        for row in A: row[k],row[j]=row[j],row[k]
        if A[k][k]==-1: A[k]=[-x for x in A[k]]
        for i in range(m):
            if i!=k and A[i][k]:
                q=A[i][k]; A[i]=[A[i][z]-q*A[k][z] for z in range(n)]
        for j in range(n):
            if j!=k and A[k][j]:
                q=A[k][j]
                for i in range(m): A[i][j]-=q*A[i][k]
        k+=1
    assert all(A[i][j]==0 for i in range(k,m) for j in range(k,n)), (m,n,k,A)
    return k

records=[]
for d in degrees:
    cols=bydeg[d]
    rows=[]
    for t in hdegrees:
        for la in bydeg.get(d-t,[]):
            rows.append([1 if horiz(mu,la) else 0 for mu in cols])
    rank=unit_reduce(rows) if rows else 0
    free=len(cols)-rank
    records.append({'degree':d,'matrixShape':[len(rows),len(cols)],'rank':rank,
                    'smithDiagonal':[1]*rank,'quotientFreeRank':free,
                    'torsionInvariantFactors':[]})
expected={4:1,5:1,6:2,7:1,8:1}
assert [(x['degree'],x['quotientFreeRank']) for x in records] == [(d,expected.get(d,0)) for d in degrees]
assert sum(x['quotientFreeRank'] for x in records)==6
payload={'inputs':{'lower':list(lower),'upper':list(upper),'degrees':degrees,'hDegrees':hdegrees,'pieriRule':'mu_i >= lambda_i >= mu_(i+1)'},'degreewiseQuotientData':records,'totalFreeRank':6,'torsionFree':True,'conclusion':'Q is isomorphic to Z^6'}
encoded=json.dumps(payload,sort_keys=True,separators=(',',':'))
print(json.dumps({'outputSha256':hashlib.sha256(encoded.encode()).hexdigest(),**payload},sort_keys=True,separators=(',',':')))"}
